        this.jteRoot = jteRoot;
        this.jteTag = jteTag;
    }

    public void convertTag(String jspTag, Consumer<Converter> parserSetup) {
        Path jspTagFile = jspRoot.resolve(jspTag);
        String relativeFilePath = jspRoot.relativize(jspTagFile).toString();
        JtpConverter converter = createConverter(relativeFilePath, readFile(jspTagFile), parserSetup);
        String jte = converter.convert();

        System.out.println(jte);

