    public JspMigrationPlan planTags(Collection<String> jspTags, Consumer<Converter> parserSetup) {
        Path normalizedJspRoot = jspRoot.toAbsolutePath().normalize();
        Path normalizedJteRoot = jteRoot.toAbsolutePath().normalize();
        Map<String, Path> selected = validateSelectedTags(jspTags, normalizedJspRoot);
        Map<Path, String> originalContents = scanUsageFiles(normalizedJspRoot);
