    @SuppressWarnings("unused")
    public void replaceUsages(String jspTag, String jteTag) {
        replaceUsages(jspRoot.resolve(jspTag), jteRoot.resolve(jteTag));
    }

    public void replaceUsages(Path jspTag, Path jteTag) {
        String oldJspTagPrefix = extractTagPrefix(jspTag);
        String oldJspTagClosing = "</" + oldJspTagPrefix.substring(1) + ">";
        String newJteFile = jteRoot.relativize(jteTag).toString().replace('\\', '/');

        IoUtils.deleteFile(jspTag);

        try (Stream<Path> stream = Files.walk(jspRoot)) {
            stream.filter(Files::isRegularFile)
                    .filter(this::isUsageFile)
                    .forEach(jspFile -> replaceUsages(jspFile, oldJspTagPrefix, oldJspTagClosing, newJteFile));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    protected String readFile(Path jspTag) {
        return IoUtils.readFile(jspTag);
    }

    private JtpConverter createConverter(String relativeFilePath, String content, Consumer<Converter> parserSetup) {
        JtpConverter converter = new JtpConverter(
                relativeFilePath,
                content.replace("\r", "").getBytes(StandardCharsets.UTF_8),
                getResourceBase(),
                relativeFilePath.endsWith(".tag"),
                new ConverterOutput()
        );

        converter.register("c:if", new JspIfConverter());
        converter.register("c:forEach", new JspForEachConverter());
        converter.register("c:choose", new JspChooseConverter());
        converter.register("c:when", new JspWhenConverter());
        converter.register("c:otherwise", new JspOtherwiseConverter());
        converter.register("c:set", new JspSetConverter());
        converter.register("fmt:message", new JstlFmtMessageConverter());
        converter.register("fmt:param", new JstlFmtParamConverter());
        converter.register(jteTag, new JspJteConverter());

        if (getNotConvertedTags() != null) {
            for (String notConvertedTag : getNotConvertedTags()) {
                converter.register(notConvertedTag, new JspNoopConverter());
            }
        }
        if (parserSetup != null) {
            parserSetup.accept(converter);
        }
        return converter;
    }

    private Map<String, Path> validateSelectedTags(Collection<String> jspTags, Path normalizedJspRoot) {
        if (jspTags == null || jspTags.isEmpty()) {
            throw new IllegalArgumentException("At least one JSP tag must be selected.");
        }

        Path realJspRoot;
        try {
            realJspRoot = normalizedJspRoot.toRealPath();
        } catch (IOException e) {
            throw new IllegalArgumentException("The JSP root does not exist: " + normalizedJspRoot, e);
        }

        Map<String, Path> result = new TreeMap<>();
        for (String input : jspTags) {
            if (input == null || input.isBlank()) {
                throw new IllegalArgumentException("JSP tag paths must not be null or blank.");
            }
            Path relative;
            try {
                relative = Path.of(input);
            } catch (InvalidPathException e) {
                throw new IllegalArgumentException("Invalid JSP tag path: " + input, e);
            }
            if (relative.isAbsolute()) {
                throw new IllegalArgumentException("JSP tag paths must be root-relative: " + input);
            }
            relative = relative.normalize();
            String normalizedRelative = relative.toString().replace('\\', '/');
            if (normalizedRelative.isBlank() || normalizedRelative.equals("..") || normalizedRelative.startsWith("../")) {
                throw new IllegalArgumentException("JSP tag path is outside the JSP root: " + input);
            }
            if (!normalizedRelative.endsWith(".tag")) {
                throw new IllegalArgumentException("JSP tag path must end with .tag: " + input);
            }
            Path absolute = normalizedJspRoot.resolve(relative).normalize();
            if (!absolute.startsWith(normalizedJspRoot)) {
                throw new IllegalArgumentException("JSP tag path is outside the JSP root: " + input);
            }
            if (Files.isSymbolicLink(absolute)) {
                throw new IllegalArgumentException("Selected JSP tag must not be a symbolic link: " + input);
            }
            if (!Files.isRegularFile(absolute, LinkOption.NOFOLLOW_LINKS)) {
                throw new IllegalArgumentException("Selected JSP tag is missing or not a regular file: " + input);
            }
            try {
                if (!absolute.toRealPath().startsWith(realJspRoot)) {
                    throw new IllegalArgumentException("JSP tag path is outside the JSP root: " + input);
                }
            } catch (IOException e) {
                throw new IllegalArgumentException("Unable to resolve selected JSP tag: " + input, e);
            }
            if (result.put(normalizedRelative, absolute) != null) {
                throw new IllegalArgumentException("Duplicate normalized JSP tag path: " + input);
            }
        }
        return result;
    }

    private Map<Path, String> scanUsageFiles(Path normalizedJspRoot) {
        Map<Path, String> result = new TreeMap<>(PATH_COMPARATOR);
        try (Stream<Path> stream = Files.walk(normalizedJspRoot)) {
            stream.filter(Files::isRegularFile)
                    .map(path -> path.toAbsolutePath().normalize())
                    .filter(this::isUsageFile)
                    .sorted(PATH_COMPARATOR)
                    .forEach(path -> result.put(path, readFile(path)));
        } catch (IOException | UncheckedIOException e) {
            throw new IllegalArgumentException("Unable to scan JSP usages under " + normalizedJspRoot, e);
        }
        return result;
    }

    private boolean isUsageFile(Path path) {
        String fileName = path.toString();
        return fileName.endsWith(".jsp") || fileName.endsWith(".jsp.inc") || fileName.endsWith(".tag");
    }

    private Map<String, Path> validateDestinations(Map<String, Path> selected, Path normalizedJteRoot) {
        Map<String, Path> result = new TreeMap<>();
        Set<Path> destinations = new HashSet<>();
        for (String relativePath : selected.keySet()) {
            String suggestion = suggestJteFile(relativePath);
            if (suggestion == null || suggestion.isBlank()) {
                throw new IllegalArgumentException("Generated JTE destination must not be null or blank for " + relativePath);
            }
            Path suggested;
            try {
                suggested = Path.of(suggestion);
            } catch (InvalidPathException e) {
                throw new IllegalArgumentException("Invalid generated JTE destination for " + relativePath + ": " + suggestion, e);
            }
            if (suggested.isAbsolute()) {
                throw new IllegalArgumentException("Generated JTE destination is outside the JTE root: " + suggestion);
            }
            Path destination = normalizedJteRoot.resolve(suggested).normalize();
            if (!destination.startsWith(normalizedJteRoot) || !resolvedPath(destination).startsWith(resolvedPath(normalizedJteRoot))) {
                throw new IllegalArgumentException("Generated JTE destination is outside the JTE root: " + suggestion);
            }
            if (!destinations.add(destination)) {
                throw new IllegalArgumentException("Generated JTE destinations collide at " + destination);
            }
            if (Files.exists(destination, LinkOption.NOFOLLOW_LINKS)) {
                throw new IllegalArgumentException("Generated JTE destination is already taken: " + destination);
            }
            result.put(relativePath, destination);
        }
        return result;
    }

    private Path resolvedPath(Path path) {
        Path existing = path;
        Deque<Path> missing = new ArrayDeque<>();
        while (existing != null && !Files.exists(existing, LinkOption.NOFOLLOW_LINKS)) {
            missing.push(existing.getFileName());
            existing = existing.getParent();
        }
        if (existing == null) {
            return path;
        }
        try {
            Path result = existing.toRealPath();
            while (!missing.isEmpty()) {
                result = result.resolve(missing.pop());
            }
            return result.normalize();
        } catch (IOException e) {
            throw new IllegalArgumentException("Unable to resolve path " + path, e);
        }
    }

    private void validateApprovedIncludes(Set<String> includes, Path normalizedJspRoot) {
        for (String include : includes) {
            resolveInclude(include, normalizedJspRoot);
        }
    }

    private void snapshotUsedIncludes(Set<String> includes, Path normalizedJspRoot, Map<Path, byte[]> snapshots) {
        for (String include : includes) {
            Path includePath = resolveInclude(include, normalizedJspRoot);
            if (!Files.isRegularFile(includePath)) {
                throw new IllegalArgumentException("Approved include is missing or not a regular file: " + include);
            }
            snapshot(includePath, snapshots);
        }
    }

    private Path resolveInclude(String include, Path normalizedJspRoot) {
        if (include == null || include.isBlank()) {
            throw new IllegalArgumentException("Approved include paths must not be null or blank.");
        }
        Path resourceBase;
        try {
            URL resourceBaseUrl = getResourceBase();
            if (!"file".equalsIgnoreCase(resourceBaseUrl.getProtocol())) {
                throw new IllegalArgumentException("Approved includes require a file resource base: " + resourceBaseUrl);
            }
            resourceBase = Path.of(resourceBaseUrl.toURI()).toAbsolutePath().normalize();
        } catch (URISyntaxException e) {
            throw new IllegalArgumentException("Invalid converter resource base.", e);
        }
        String relativeInclude = include.replace('\\', '/');
        while (relativeInclude.startsWith("/")) {
            relativeInclude = relativeInclude.substring(1);
        }
        Path resolved = resourceBase.resolve(relativeInclude).toAbsolutePath().normalize();
        if (!resolved.startsWith(normalizedJspRoot)) {
            throw new IllegalArgumentException("Approved include is outside the JSP root: " + include);
        }
        if (Files.exists(resolved) && !resolvedPath(resolved).startsWith(resolvedPath(normalizedJspRoot))) {
            throw new IllegalArgumentException("Approved include is outside the JSP root: " + include);
        }
        return resolved;
    }

    private void snapshot(Path path, Map<Path, byte[]> snapshots) {
        Path normalized = path.toAbsolutePath().normalize();
        if (snapshots.containsKey(normalized)) {
            return;
        }
        try {
            snapshots.put(normalized, Files.readAllBytes(normalized));
        } catch (IOException e) {
            throw new IllegalArgumentException("Unable to snapshot " + normalized, e);
        }
    }

    private List<String> conversionOrder(Map<String, Set<String>> dependencies) {
        Set<String> converted = new HashSet<>();
        List<String> result = new ArrayList<>();
        while (result.size() < dependencies.size()) {
