package gg.jte.convert.jsp;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.IOException;
import java.net.URL;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.assertj.core.api.Assertions.catchThrowable;

class JspMigrationPlanTest {
    @TempDir
    Path tempDir;

    @Test
    void plansAndCommitsWithoutMutatingDuringPlanning() throws IOException {
        Path jspRoot = Files.createDirectories(tempDir.resolve("jsp"));
        Path jteRoot = tempDir.resolve("jte");
        Path tag = write(jspRoot.resolve("my/simple.tag"), "<p>Hello</p>");
        Path usage = write(jspRoot.resolve("usage.jsp"), "<my:simple/>");
        Path unrelated = write(jspRoot.resolve("unrelated.txt"), "unchanged");

        JspMigrationPlan plan = new JspToJteConverter(jspRoot, jteRoot, "my:jte")
                .planTags(List.of("my/simple.tag"), converter -> converter.setPrefix("@import example.SimpleBean\n"));

        Path destination = jteRoot.resolve("my/simple.jte").toAbsolutePath().normalize();
        assertThat(plan.getConversionOrder()).containsExactly(tag.toAbsolutePath().normalize());
        assertThat(plan.getDeletes()).containsExactly(tag.toAbsolutePath().normalize());
        assertThat(plan.getWrites()).containsKeys(destination, usage.toAbsolutePath().normalize());
        assertThat(plan.getWrites().get(destination)).startsWith("@import example.SimpleBean");
        assertThat(tag).exists();
        assertThat(destination).doesNotExist();
        assertThat(usage).hasContent("<my:simple/>");
        assertThatThrownBy(() -> plan.getWrites().put(destination, "changed")).isInstanceOf(UnsupportedOperationException.class);
        assertThatThrownBy(() -> plan.getDeletes().clear()).isInstanceOf(UnsupportedOperationException.class);
        assertThatThrownBy(() -> plan.getConversionOrder().clear()).isInstanceOf(UnsupportedOperationException.class);

        plan.commit();

        assertThat(tag).doesNotExist();
        assertThat(destination).hasContent(plan.getWrites().get(destination));
        assertThat(usage).hasContent("<my:jte jte=\"my/simple.jte\"/>");
        assertThat(unrelated).hasContent("unchanged");
        assertThatThrownBy(plan::commit).isInstanceOf(IllegalStateException.class);
    }

    @Test
    void reportsAllStalePathsBeforeMutation() throws IOException {
        Path jspRoot = Files.createDirectories(tempDir.resolve("jsp"));
        Path jteRoot = tempDir.resolve("jte");
        Path tag = write(jspRoot.resolve("my/simple.tag"), "<p>Hello</p>");
        Path usage = write(jspRoot.resolve("usage.jsp"), "<my:simple/>");
        JspMigrationPlan plan = new JspToJteConverter(jspRoot, jteRoot, "my:jte")
                .planTags(List.of("my/simple.tag"), null);
        Path destination = jteRoot.resolve("my/simple.jte").toAbsolutePath().normalize();

        Files.writeString(tag, "changed tag");
        Files.writeString(usage, "changed usage");
        Files.createDirectories(destination.getParent());
        Files.writeString(destination, "occupied");

        Throwable throwable = catchThrowable(plan::commit);

        assertThat(throwable).isInstanceOf(StaleJspMigrationPlanException.class);
        StaleJspMigrationPlanException stale = (StaleJspMigrationPlanException) throwable;
        assertThat(stale.getChangedPaths()).containsExactlyElementsOf(
                List.of(destination, tag.toAbsolutePath().normalize(), usage.toAbsolutePath().normalize()).stream().sorted().toList());
        assertThat(tag).hasContent("changed tag");
        assertThat(usage).hasContent("changed usage");
        assertThat(destination).hasContent("occupied");
    }

    @Test
    void ordersParsedTagDependenciesIndependentlyOfInputOrder() throws IOException {
        Path webRoot = Files.createDirectories(tempDir.resolve("web"));
        Path jteRoot = tempDir.resolve("jte");
        write(webRoot.resolve("WEB-INF/tld/my.tld"), tld());
        Path first = write(webRoot.resolve("WEB-INF/tags/my/first.tag"), tagHeader() + "<p>first</p>");
        Path second = write(webRoot.resolve("WEB-INF/tags/my/second.tag"), tagHeader() + "<my:first/>");
        write(webRoot.resolve("usage.jsp"), "<%@ taglib uri=\"urn:my\" prefix=\"my\" %><my:second/>");

        JspMigrationPlan plan = new ResourceBasedConverter(webRoot, jteRoot)
                .planTags(List.of("WEB-INF/tags/my/second.tag", "WEB-INF/tags/my/first.tag"), null);

        assertThat(plan.getConversionOrder()).containsExactly(
                first.toAbsolutePath().normalize(), second.toAbsolutePath().normalize());
        assertThat(plan.getWrites().get(jteRoot.resolve("WEB-INF/tags/my/second.jte").toAbsolutePath().normalize()))
                .contains("@template.WEB-INF.tags.my.first(");
    }

    @Test
    void surfacesParserSetupFailureUnchanged() throws IOException {
        Path jspRoot = Files.createDirectories(tempDir.resolve("jsp"));
        Path jteRoot = tempDir.resolve("jte");
        write(jspRoot.resolve("my/simple.tag"), "<p>Hello</p>");
        IllegalStateException expected = new IllegalStateException("setup failed");

        Throwable actual = catchThrowable(() -> new JspToJteConverter(jspRoot, jteRoot, "my:jte")
                .planTags(List.of("my/simple.tag"), converter -> {
                    throw expected;
                }));

        assertThat(actual).isSameAs(expected);
    }

    @Test
    void ignoresTagLookingTextInJspComments() throws IOException {
        Path jspRoot = Files.createDirectories(tempDir.resolve("jsp"));
        Path jteRoot = tempDir.resolve("jte");
        write(jspRoot.resolve("my/simple.tag"), "<%-- <other:missing/> --%><p>Hello</p>");

        JspMigrationPlan plan = new JspToJteConverter(jspRoot, jteRoot, "my:jte")
                .planTags(List.of("my/simple.tag"), null);

        assertThat(plan.getWrites()).hasSize(1);
    }

    private Path write(Path path, String content) throws IOException {
        Files.createDirectories(path.getParent());
        return Files.writeString(path, content);
    }

    private String tagHeader() {
        return "<%@ taglib uri=\"urn:my\" prefix=\"my\" %>\n";
    }

    private String tld() {
        return """
                <?xml version="1.0" encoding="UTF-8" ?>
                <taglib xmlns="http://java.sun.com/xml/ns/j2ee" version="2.0">
                  <tlib-version>1.0</tlib-version>
                  <short-name>my</short-name>
                  <uri>urn:my</uri>
                  <tag-file><name>first</name><path>/WEB-INF/tags/my/first.tag</path></tag-file>
                  <tag-file><name>second</name><path>/WEB-INF/tags/my/second.tag</path></tag-file>
                  <tag>
                    <name>jte</name>
                    <tag-class>example.JteTag</tag-class>
                    <body-content>scriptless</body-content>
                    <attribute><name>jte</name><required>true</required><rtexprvalue>true</rtexprvalue></attribute>
                    <dynamic-attributes>true</dynamic-attributes>
                  </tag>
                </taglib>
                """;
    }

    private static class ResourceBasedConverter extends JspToJteConverter {
        private final Path resourceBase;

        private ResourceBasedConverter(Path jspRoot, Path jteRoot) {
            super(jspRoot, jteRoot, "my:jte");
            resourceBase = jspRoot;
        }

        @Override
        protected URL getResourceBase() {
            try {
                return resourceBase.toUri().toURL();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}
